using System;using System.IO;using System.Collections.Generic;using System.Xml;using System.Xml.Serialization;
public class Offline70GoldReceipt {public string Id;public uint Amount;}
public class Offline70GoldState {public int Format=1;public ushort RoleId=Offline70RoleScopeFG202.Current;public uint Earned;public List<Offline70GoldReceipt> Receipts=new List<Offline70GoldReceipt>();}
class Offline70GoldDrop {internal ushort Slot;internal uint Amount;internal string Receipt;}
class Offline70GoldLoot {
 static readonly XmlSerializer Serializer=new XmlSerializer(typeof(Offline70GoldState));
 internal const uint Limit=999999999;
 static void Validate(Offline70GoldState s){if(s==null||s.Format!=1||s.RoleId==0||s.Earned>Limit||s.Receipts==null||s.Receipts.Count>10000)throw new InvalidDataException("Gold store profile");HashSet<string> ids=new HashSet<string>();ulong sum=0;foreach(Offline70GoldReceipt r in s.Receipts){if(r==null||r.Id==null||r.Id.Length!=37||!ids.Add(r.Id)||r.Amount<15||r.Amount>20)throw new InvalidDataException("Gold receipt profile");Guid parsed;try{parsed=new Guid(r.Id.Substring(0,32));}catch(FormatException){throw new InvalidDataException("Gold receipt run");}if(parsed==Guid.Empty||r.Id[32]!='-'||String.CompareOrdinal(r.Id.Substring(33),"2000")<0||String.CompareOrdinal(r.Id.Substring(33),"2003")>0)throw new InvalidDataException("Gold receipt slot");sum+=r.Amount;}if(sum!=s.Earned)throw new InvalidDataException("Gold receipt total");}
 internal static Offline70GoldState Load(string path){if(!File.Exists(path))return new Offline70GoldState();if(new FileInfo(path).Length>2000000)throw new InvalidDataException("Gold store bounds");using(FileStream f=File.OpenRead(path))using(XmlTextReader r=new XmlTextReader(f)){r.ProhibitDtd=true;r.XmlResolver=null;Offline70GoldState s=(Offline70GoldState)Serializer.Deserialize(r);Validate(s);return s;}}
 internal static uint Total(Offline70GoldState s,uint questGold){Validate(s);if(questGold!=0&&questGold!=100||s.Earned>Limit-questGold)throw new InvalidDataException("Gold balance limit");return s.Earned+questGold;}
 internal static Offline70GoldState Pickup(string path,Offline70GoldDrop drop,uint questGold,out bool duplicate){
  string full=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(full));duplicate=false;
  if(drop==null||drop.Slot<2000||drop.Slot>2003||drop.Amount<15||drop.Amount>20||drop.Receipt==null||!drop.Receipt.EndsWith("-"+drop.Slot))throw new InvalidDataException("Unregistered gold drop");
  using(FileStream held=new FileStream(full+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){Offline70GoldState s=Load(full);foreach(Offline70GoldReceipt r in s.Receipts)if(r.Id==drop.Receipt){if(r.Amount!=drop.Amount)throw new InvalidDataException("Gold receipt amount differs");duplicate=true;return s;}
   if(s.Receipts.Count>=10000||drop.Amount>Limit-Total(s,questGold))throw new InvalidDataException("Gold capacity");s.Earned+=drop.Amount;s.Receipts.Add(new Offline70GoldReceipt{Id=drop.Receipt,Amount=drop.Amount});Validate(s);
   string temp=full+".pending-"+Guid.NewGuid().ToString("N"),backup=full+Offline70StoreBackupFG354.Suffix;try{using(FileStream f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){Serializer.Serialize(f,s);f.Flush();}Offline70GoldState candidate=Load(temp);if(candidate.Earned!=s.Earned||candidate.Receipts.Count!=s.Receipts.Count)throw new InvalidDataException("Gold readback");if(File.Exists(full))File.Replace(temp,full,backup);else File.Move(temp,full);candidate=Load(full);if(candidate.Earned!=s.Earned||candidate.Receipts[candidate.Receipts.Count-1].Id!=drop.Receipt)throw new InvalidDataException("Gold committed readback");return candidate;}finally{if(File.Exists(temp))File.Delete(temp);}
  }
 }
 // Compiled current CN70 PVF: Lv1 common row(1,18,15), probability row(1,15,986,...), normal difficulty and ordinary monster multipliers1.
 internal static uint Roll(int chance,int variance,bool forcedTest){if(chance<0||chance>10000||variance< -15||variance>15)throw new InvalidDataException("Gold random bounds");if(!forcedTest&&chance>=986)return 0;return (uint)(18+(int)Math.Floor(18.0*variance/100));}
 internal static Offline70GoldDrop Spawn(ushort uid,string run,Random rng,bool forcedTest){if(uid<100||uid>103)throw new InvalidDataException("Gold monster bounds");uint amount=Roll(rng.Next(0,10001),rng.Next(-15,16),forcedTest);return amount==0?null:new Offline70GoldDrop{Slot=(ushort)(2000+uid-100),Amount=amount,Receipt=run+"-"+(2000+uid-100)};}
 internal static byte[] DeathBody(ushort uid,Offline70GoldDrop drop){if(drop==null)return Offline70RoleProtocol.MonsterDeathBody(uid);if(uid<100||uid>103||drop.Slot!=2000+uid-100||drop.Amount<15||drop.Amount>20)throw new InvalidDataException("Gold death profile");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(uid);w.Write((byte)1);w.Write(drop.Slot);w.Write((uint)0);w.Write(drop.Amount);w.Write((ushort)0);w.Write((byte)0);w.Write((ushort)0);w.Write((uint)0);w.Write(new byte[6]);w.Write((ushort)65535);w.Write(new byte[]{0,255,0});return m.ToArray();}}
 internal static byte[] DeathReply(ushort uid,Offline70GoldDrop drop,Offline70Role role,byte[] keys){Offline70TownProtocol.Validate(role,keys);return Offline70RoleProtocol.Packet(0,38,Offline70AreaCipher.Crypt(Pad(DeathBody(uid,drop),8),keys,10,true));}
 internal static byte[] Pad(byte[] body,int block){byte[] pad=new byte[(body.Length+block-1)/block*block];body.CopyTo(pad,0);return pad;}
 internal static byte[] PickupBody(ushort slot,uint amount){if(slot<2000||slot>2003||amount<15||amount>20)throw new InvalidDataException("Gold pickup profile");byte[] b=new byte[25];BitConverter.GetBytes(slot).CopyTo(b,0);BitConverter.GetBytes((ushort)1).CopyTo(b,2);b[4]=1;BitConverter.GetBytes(amount).CopyTo(b,5);return b;}
 internal static byte[] PickupReply(ushort slot,uint amount,byte[] keys){return Offline70RoleProtocol.Packet(0,39,Offline70GoldCipher.Crypt(Pad(PickupBody(slot,amount),8),keys,11,true));}
 internal static byte[] Ack(byte[] keys){return Offline70RoleProtocol.Packet(1,46,Offline70GoldCipher.Crypt(Pad(new byte[]{1},16),keys,4,true));}
 // Original 105D9A0(1,46) returns AL=0: command46 does NOT append the
 // death command's MD5 fold. Its eight native fields fill exactly16 bytes.
 internal static byte[] ParsePlain(byte[] encrypted,byte[] keys){if(encrypted==null||encrypted.Length!=16)throw new InvalidDataException("Gold request cipher length");byte[] p=Offline70GoldCipher.Crypt(encrypted,keys,4,false);ushort slot=BitConverter.ToUInt16(p,0);if(slot<2000||slot>2003||p[2]!=0||p[3]>1)throw new InvalidDataException("Gold request routing");foreach(int at in new int[]{4,6,10,12})if(BitConverter.ToUInt16(p,at)>4096)throw new InvalidDataException("Gold coordinate bounds");return p;}
}
